import{_ as a,o as i,c as n,a6 as e}from"./chunks/framework.BrkgobfX.js";const k=JSON.parse('{"title":"安全响应头","description":"一份逐条讲清「挡什么、怎么配、有什么代价」的响应头清单——点击劫持、MIME 嗅探、Referer 泄露、跨源隔离，以及那些已经过时不该再配的头。","frontmatter":{"title":"安全响应头","description":"一份逐条讲清「挡什么、怎么配、有什么代价」的响应头清单——点击劫持、MIME 嗅探、Referer 泄露、跨源隔离，以及那些已经过时不该再配的头。","source":"https://daiw.org/manual/web-security/security-headers"},"headers":[],"relativePath":"manual/computer-programming/web-security/security-headers.md","filePath":"manual/computer-programming/web-security/security-headers.md"}'),t={name:"manual/computer-programming/web-security/security-headers.md"};function r(p,s,l,o,h,d){return i(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="安全响应头" tabindex="-1">安全响应头 <a class="header-anchor" href="#安全响应头" aria-label="Permalink to &quot;安全响应头&quot;">​</a></h1><p>一份逐条讲清「挡什么、怎么配、有什么代价」的响应头清单——点击劫持、MIME 嗅探、Referer 泄露、跨源隔离，以及那些已经过时不该再配的头。</p><p>这是整个专栏里<strong>投入产出比最高</strong>的一章：几行配置，挡掉一批攻击，通常几十分钟就能上完。</p><h2 id="一份完整配置" tabindex="-1">一份完整配置 <a class="header-anchor" href="#一份完整配置" aria-label="Permalink to &quot;一份完整配置&quot;">​</a></h2><p>先给结论，再逐条解释：</p><div class="language-nginx vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ── 必配 ──</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">add_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Strict-Transport-Security </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;max-age=31536000; includeSubDomains&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> always;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">add_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Content-Type-Options </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;nosniff&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> always;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">add_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Referrer-Policy </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;strict-origin-when-cross-origin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> always;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">add_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Content-Security-Policy </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;default-src &#39;self&#39;; frame-ancestors &#39;none&#39;; base-uri &#39;none&#39;; object-src &#39;none&#39;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ── 强烈建议 ──</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">add_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Frame-Options </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;DENY&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> always;              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 给老浏览器兜底</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">add_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Permissions-Policy </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;camera=(), microphone=(), geolocation=(), payment=()&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ── 需要跨源隔离时（SharedArrayBuffer 等）──</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># add_header Cross-Origin-Opener-Policy &quot;same-origin&quot; always;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># add_header Cross-Origin-Embedder-Policy &quot;require-corp&quot; always;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># add_header Cross-Origin-Resource-Policy &quot;same-origin&quot; always;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong><code>always</code> 参数不能省。</strong> 不加的话，Nginx 只在 2xx/3xx 响应上添加这些头，<strong>4xx 和 5xx 页面不带</strong>。而错误页恰恰是攻击者最常访问的路径，也是最容易泄露信息的地方。</p><p>另外记住<a href="/Front2Full/manual/computer-programming/web-security/nginx-baseline">基线那一章</a>提过的坑：<strong><code>add_header</code> 在子块里是覆盖不是合并</strong>。把这些头抽成 <code>include</code> 文件，在每个 location 里引一次。</p></div><h2 id="逐条拆解" tabindex="-1">逐条拆解 <a class="header-anchor" href="#逐条拆解" aria-label="Permalink to &quot;逐条拆解&quot;">​</a></h2><h3 id="strict-transport-security-hsts" tabindex="-1">Strict-Transport-Security（HSTS） <a class="header-anchor" href="#strict-transport-security-hsts" aria-label="Permalink to &quot;Strict-Transport-Security（HSTS）&quot;">​</a></h3><p><strong>挡什么</strong>：SSL 剥离攻击。用户输入 <code>example.com</code>（没带 https），中间人把跳转拦下来，一直用 HTTP 通信。HSTS 让浏览器<strong>记住「这个域只能用 HTTPS」</strong>，之后连尝试都不会尝试 HTTP。</p><p><strong>代价</strong>：<a href="/Front2Full/manual/computer-programming/web-security/tls-and-certs">证书那一章</a>详细讲过——<code>includeSubDomains</code> 和 <code>preload</code> 能把你锁死，必须分阶段上。</p><h3 id="x-content-type-options-nosniff" tabindex="-1">X-Content-Type-Options: nosniff <a class="header-anchor" href="#x-content-type-options-nosniff" aria-label="Permalink to &quot;X-Content-Type-Options: nosniff&quot;">​</a></h3><p><strong>挡什么</strong>：MIME 嗅探。浏览器发现 <code>Content-Type</code> 和内容对不上时，会「聪明地」猜测真实类型。</p><p><strong>为什么危险</strong>：用户上传了一个 <code>avatar.jpg</code>，内容其实是 HTML+JS。你返回 <code>Content-Type: image/jpeg</code>，但浏览器嗅探后决定「这是 HTML」，于是<strong>执行了里面的脚本</strong>——在你的域下。一个头像上传变成了存储型 XSS。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add_header X-Content-Type-Options &quot;nosniff&quot; always;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>代价：几乎为零。</strong> 唯一的要求是<strong>你必须设对 <code>Content-Type</code></strong>——如果你的服务器给 CSS 返回 <code>text/plain</code>，加了 nosniff 之后样式会失效。这其实是好事，逼你修正配置。</p><h3 id="referrer-policy" tabindex="-1">Referrer-Policy <a class="header-anchor" href="#referrer-policy" aria-label="Permalink to &quot;Referrer-Policy&quot;">​</a></h3><p><strong>挡什么</strong>：URL 泄露。默认情况下，用户从你的页面点击外链时，浏览器会把<strong>当前完整 URL</strong> 放进 <code>Referer</code> 头发给对方。</p><p><strong>真实泄露场景</strong>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://example.com/reset-password?token=abc123xyz</span></span>
<span class="line"><span>                    ↑ 用户在这个页面点了一个外部链接</span></span>
<span class="line"><span>                    → 密码重置 token 就到了第三方的日志里</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>同类的还有：包含订单号、用户 ID、搜索关键词的 URL。</p><table tabindex="0"><thead><tr><th>值</th><th>行为</th></tr></thead><tbody><tr><td><code>no-referrer</code></td><td>完全不发。最安全，但会让你的站在别人的统计里变成「直接访问」</td></tr><tr><td><code>same-origin</code></td><td>只在同源时发</td></tr><tr><td><strong><code>strict-origin-when-cross-origin</code></strong></td><td><strong>推荐</strong>：同源发完整 URL，跨源只发源（<code>https://example.com</code>），降级到 HTTP 时不发</td></tr></tbody></table><p><strong>根本对策还是「敏感信息不要放进 URL」</strong>——URL 会进浏览器历史、服务器日志、CDN 日志、Referer 头，泄露面太广。响应头只是兜底。</p><h3 id="frame-ancestors-x-frame-options" tabindex="-1">frame-ancestors / X-Frame-Options <a class="header-anchor" href="#frame-ancestors-x-frame-options" aria-label="Permalink to &quot;frame-ancestors / X-Frame-Options&quot;">​</a></h3><p><strong>挡什么</strong>：点击劫持（clickjacking）。攻击者把你的页面放进一个透明的 iframe，上面盖一层诱导性内容：</p><div class="language-html vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">style</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  iframe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">opacity</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">position</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">absolute</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">z-index</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">width</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">400</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">px</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">height</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">px</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; }</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  button</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">position</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">absolute</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">z-index</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">style</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">button</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;点击领取奖品&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">button</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">iframe</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://example.com/account/delete&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">iframe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>用户以为在点「领取奖品」，实际点的是 iframe 里你的「确认删除账号」按钮。<strong>他的会话是有效的，操作会真的执行。</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 新标准（CSP 的一部分）</span></span>
<span class="line"><span>Content-Security-Policy: frame-ancestors &#39;none&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 老标准，给不支持 CSP 的浏览器兜底</span></span>
<span class="line"><span>X-Frame-Options: DENY</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><strong>两个都配</strong>：<code>frame-ancestors</code> 优先级更高、更灵活（支持多来源白名单），<code>X-Frame-Options</code> 覆盖老浏览器。</p><p>需要被特定站点嵌入时：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Content-Security-Policy: frame-ancestors &#39;self&#39; https://partner.example.com</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong><code>X-Frame-Options: ALLOW-FROM</code> 已被废弃</strong>，主流浏览器都不支持了。需要白名单就只能用 <code>frame-ancestors</code>。</p></div><h3 id="permissions-policy" tabindex="-1">Permissions-Policy <a class="header-anchor" href="#permissions-policy" aria-label="Permalink to &quot;Permissions-Policy&quot;">​</a></h3><p><strong>挡什么</strong>：限制页面（<strong>包括其中的 iframe</strong>）能使用哪些浏览器能力。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Permissions-Policy: camera=(), microphone=(), geolocation=(), payment=(), usb=(), interest-cohort=()</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>()</code> 表示「谁都不许用」。<strong>主要价值在于限制嵌入的第三方内容</strong>——你嵌了一个广告 iframe，它不该能调用摄像头。</p><p>即使你的站点根本不用这些能力，也建议显式关掉：<strong>万一将来出现 XSS，攻击者也无法调用摄像头或定位。</strong></p><h3 id="cross-origin-三兄弟" tabindex="-1">Cross-Origin-* 三兄弟 <a class="header-anchor" href="#cross-origin-三兄弟" aria-label="Permalink to &quot;Cross-Origin-* 三兄弟&quot;">​</a></h3><p>这三个是较新的隔离机制，主要为了防御 Spectre 类的侧信道攻击：</p><table tabindex="0"><thead><tr><th>头</th><th>作用</th></tr></thead><tbody><tr><td><code>Cross-Origin-Opener-Policy: same-origin</code></td><td>切断与 <code>window.open</code> 打开者/被打开者的引用关系</td></tr><tr><td><code>Cross-Origin-Embedder-Policy: require-corp</code></td><td>要求所有跨源资源显式声明允许被嵌入</td></tr><tr><td><code>Cross-Origin-Resource-Policy: same-origin</code></td><td>声明本资源不允许被跨源加载</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>COOP + COEP 会打破很多第三方集成。</strong> 开启 <code>require-corp</code> 后，所有跨源资源（图片、脚本、iframe）都必须带 <code>Cross-Origin-Resource-Policy</code> 头或走 CORS——大量第三方 CDN 和统计脚本不满足这个要求，会直接加载失败。</p><p><strong>除非你确实需要 <code>SharedArrayBuffer</code> 或高精度计时器，否则不必开。</strong> 这三个头是「有明确需求才配」，不是通用基线。</p></div><h2 id="不该再配的过时头" tabindex="-1">不该再配的过时头 <a class="header-anchor" href="#不该再配的过时头" aria-label="Permalink to &quot;不该再配的过时头&quot;">​</a></h2><table tabindex="0"><thead><tr><th>头</th><th>为什么别配</th></tr></thead><tbody><tr><td><code>X-XSS-Protection</code></td><td>浏览器内置的 XSS 过滤器<strong>已被全部移除</strong>，因为它自身引入过漏洞。配 <code>1; mode=block</code> 无效，配错还可能有害。<strong>建议显式设为 <code>0</code> 或干脆不发</strong></td></tr><tr><td><code>Expect-CT</code></td><td>已废弃，CT 现在是强制要求，不需要这个头</td></tr><tr><td><code>Public-Key-Pins</code>（HPKP）</td><td><strong>已废弃且危险</strong>——配错会把自己的域名锁死数月，无法挽回。绝对不要用</td></tr><tr><td><code>X-Frame-Options: ALLOW-FROM</code></td><td>无浏览器支持，用 <code>frame-ancestors</code></td></tr></tbody></table><h2 id="cookie-属性也算「响应头安全」" tabindex="-1">Cookie 属性也算「响应头安全」 <a class="header-anchor" href="#cookie-属性也算「响应头安全」" aria-label="Permalink to &quot;Cookie 属性也算「响应头安全」&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Set-Cookie: session=abc;</span></span>
<span class="line"><span>            HttpOnly;               ← JS 读不到，XSS 偷不走</span></span>
<span class="line"><span>            Secure;                 ← 只在 HTTPS 上发送</span></span>
<span class="line"><span>            SameSite=Lax;           ← 限制跨站携带</span></span>
<span class="line"><span>            Path=/;</span></span>
<span class="line"><span>            Max-Age=3600            ← 别用超长有效期</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>不写 <code>Domain</code> 属性——<a href="/Front2Full/manual/computer-programming/web-security/subdomain-takeover">子域名接管那一章</a>讲过，不写的话 Cookie 只对当前主机生效，子域名被接管也偷不走。</p><p><strong>前缀是个额外的保险</strong>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Set-Cookie: __Host-session=abc; Secure; Path=/; SameSite=Lax</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>__Host-</code> 前缀是浏览器强制的约束：<strong>必须有 <code>Secure</code>、必须 <code>Path=/</code>、不能有 <code>Domain</code></strong>。任何不满足的 <code>Set-Cookie</code> 会被浏览器直接丢弃。这能防止子域名给主域写 Cookie（Cookie tossing 攻击）。</p><h2 id="一条命令自查" tabindex="-1">一条命令自查 <a class="header-anchor" href="#一条命令自查" aria-label="Permalink to &quot;一条命令自查&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">example.com</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sSI</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -iE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;strict-transport|content-security|x-frame|x-content-type|referrer-policy|permissions-policy|set-cookie|^server|x-powered-by&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;── 404 页也要有（验证 always）──&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sSI</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/definitely-not-exist</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -icE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;strict-transport|x-frame|nosniff&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><strong>第二条命令是关键</strong>：很多人配了头但漏了 <code>always</code>，或者被子块的 <code>add_header</code> 覆盖了。打一个 404 一试便知。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>必配四件套：<strong>HSTS、nosniff、Referrer-Policy、CSP</strong>（含 <code>frame-ancestors</code>）。</li><li><strong><code>always</code> 不能省</strong>，否则错误页不带头；<code>add_header</code> 在子块里是覆盖不是合并。</li><li><code>nosniff</code> 挡的是「上传的图片被当 HTML 执行」这类存储型 XSS，代价几乎为零。</li><li>Referrer 泄露的<strong>根本对策是「别把敏感信息放 URL」</strong>，响应头只是兜底。</li><li><strong>COOP/COEP 会打破第三方集成</strong>，有明确需求才配。</li><li><code>X-XSS-Protection</code>、HPKP 等已过时甚至有害，<strong>别再配</strong>。</li><li>Cookie 用 <code>__Host-</code> 前缀能防子域名写 Cookie。</li></ul><p>下一章讲前端最后一块、也是最容易失控的一块。👉 <a href="/Front2Full/manual/computer-programming/web-security/frontend-supply-chain">前端供应链</a></p>`,55)])])}const g=a(t,[["render",r]]);export{k as __pageData,g as default};
